VALUES (NULL, NULL, 26193, 'Uncharted: The Lost Legacy', 'Uncharted: The Lost Legacy', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tp9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4v8.jpg', 'Uncharted: The Lost Legacy is a single-player action-adventure game played from a third-person perspective, and a standalone expansion in the Uncharted series. Players guide treasure hunter Chloe Frazer through towns, ruins, and temples across the Western Ghats of India, using firearms, melee combat, and stealth against hostile forces. Gameplay combines gunfights, climbing and platforming, environmental puzzles, and vehicle sections across larger, more open environments than earlier entries. It also grants access to the multiplayer component of Uncharted 4.', 'https://www.igdb.com/games/uncharted-the-lost-legacy', '["PlayStation 4"]', NULL, 8.5, 0, 9.49, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
