VALUES (NULL, NULL, 565, 'Uncharted 2: Among Thieves', 'Uncharted 2: Among Thieves', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1tnb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/y8m7mjpio9dach1mdxta.jpg', 'In the sequel to Drake''s Fortune, Nathan Drake comes across a map that showcases the location of Marco Polo''s missing ships. It takes him on a journey to find the infamous Cintamani Stone, and uncover the truth behind it.', 'https://www.igdb.com/games/uncharted-2-among-thieves', '["PlayStation 3"]', NULL, 9.2, 0, 8.06, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
