VALUES (NULL, NULL, 19319, 'Curious Expedition', 'Curious Expedition', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6mh1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar730.jpg', 'Curious Expedition is a roguelike expedition simulation set in the late 19th century. Together with famous personalities you will venture on unprecedented expeditions to regions never explored before for fame, science and treasures.', 'https://www.igdb.com/games/curious-expedition', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 7.7, 0, 7.52, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
