VALUES (NULL, NULL, 1404, 'Metal Slug', 'Metal Slug', 'game', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20gf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3rq3.jpg', 'Metal Slug is a 1996 run-and-gun arcade video game originally developed by Nazca Corporation and released by SNK for the Neo Geo MVS. It is the first installment in the eponymous series. Set in 2028, players assume the role of Peregrine Falcon Strike Force soldiers Marco Rossi and Tarma Roving in a fight against the Rebel Army led by Donald Morden and overthrow his coup d''état to prevent a New World Order.', 'https://www.igdb.com/games/metal-slug', '["Arcade", "Neo Geo AES", "PlayStation 3", "Linux", "Wii", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "PlayStation Portable", "Neo Geo CD"]', NULL, 8.2, 0, 7.04, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
