VALUES (NULL, NULL, 5447, 'Stonehearth', 'Stonehearth', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24ug.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardxn.jpg', 'Pioneer a living world full of warmth, heroism, and mystery. Help a small group of settlers build a home for themselves in a forgotten land. Establish a food supply, build shelter, defend your people, monitor their moods, and find a way to grow and expand, facing challenges at every step.', 'https://www.igdb.com/games/stonehearth', '["PC (Microsoft Windows)"]', NULL, 7.4, 0, 0.0, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
