VALUES (NULL, NULL, 51578, 'Desolate', 'Desolate', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1j11.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4yj.jpg', 'DESOLATE is a first person survival horror. Form a research team with up to 4 other players and explore an open world filled with mysteries and unsolved questions or do it all by yourself.', 'https://www.igdb.com/games/desolate', '["PC (Microsoft Windows)"]', NULL, 7.5, 0, 9.03, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
