VALUES (NULL, NULL, 305159, 'Atomfall', 'Atomfall', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9dar.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar36u9.jpg', 'A nuclear disaster has left an area of Britain in tatters. Atomfall, a new survival-action game, will see you explore, scavenge, craft, barter and fight your way through beautifully recreated scenery in search of answers.', 'https://www.igdb.com/games/atomfall', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.3, 0, 6.59500000000000064e+00, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
