VALUES (NULL, NULL, 128948, 'Industria', 'Industria', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7za9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfrk.jpg', 'Industria is a first-person shooter that takes you from East Berlin into a parallel reality, shortly before the end of the Cold War. On the search for a missing work colleague, you decipher a dark past in a mysterious and surreal steampunk world.', 'https://www.igdb.com/games/industria', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 9.02, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
