VALUES (NULL, NULL, 347869, 'The Expanse: Osiris Reborn', 'The Expanse: Osiris Reborn', 'game', 2027, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9xoa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3omq.jpg', 'The Expanse: Osiris Reborn is a third-person Action RPG set in The Expanse universe. You’re no hero — just a merc caught in the wrong place at the wrong time, trying to hold your crew together and keep the ship up and running. Your choices will shape your story.', 'https://www.igdb.com/games/the-expanse-osiris-reborn', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 7.03, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
