VALUES (NULL, NULL, 10160, 'Heat Signature', 'Heat Signature', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qrb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arotj.jpg', 'Fly your tiny defenceless pod up to larger ships, dock with their airlock, and sneak inside. Once you''re in, you creep through their corridors, ambushing guards, hiding bodies, stealing new weapons, blowing them up from the inside, or hijacking their turrets and even the whole ship.', 'https://www.igdb.com/games/heat-signature', '["PC (Microsoft Windows)"]', NULL, 7.9, 0, 10.16, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
