VALUES (NULL, NULL, 150433, 'Ripout', 'Ripout', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7nqb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aritm.jpg', 'Ripout is an online Co-Op horror FPS that will have players fight their way through procedurally generated derelict ships filled with mutants capable of reconfiguring their alien bodies. Survive with your trusty Pet Gun companion, collect loot, and customize your character to fit your playstyle.', 'https://www.igdb.com/games/ripout', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 9.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
