VALUES (NULL, NULL, 132995, 'Marauders', 'Marauders', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co548c.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1r37.jpg', 'Become a space pirate and work solo, or in a squad of up to 3 other players to navigate a hostile battleground, survive intense combat encounters with other teams and AI opponents for invaluable loot, craft new weapons and gear, and salvage what you’ll need to survive.', 'https://www.igdb.com/games/marauders', '["PC (Microsoft Windows)"]', NULL, 7.0, 0, 1.01200000000000009e+01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
