VALUES (NULL, NULL, 11064, 'Shadow Warrior 2', 'Shadow Warrior 2', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coavqn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar755.jpg', '"Shadow Warrior 2 is the stunning evolution of Flying Wild Hog’s offbeat first-person shooter following the further misadventures of former corporate shogun Lo Wang. Now surviving as a reclusive mercenary on the edge of a corrupted world, the formidable warrior must again wield a devastating combination of guns, blades, magic and wit to strike down the demonic legions overwhelming the world. Battle alongside allies online in four-player co-op or go it alone in spectacular procedurally-generated landscapes to complete daring missions and collect powerful new weapons, armor, and arcane relics of legend."', 'https://www.igdb.com/games/shadow-warrior-2', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.6, 0, 8.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
