VALUES (NULL, NULL, 1529, 'Jak II', 'Jak II', 'game', 2003, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2agi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/uo5h2tgli6sdwq6am1eo.jpg', 'Jak II is an open-world platform, third-person shooter, and an action-adventure video game. It is the second game of the Jak and Daxter series and a sequel to Jak and Daxter: The Precursor Legacy.', 'https://www.igdb.com/games/jak-ii', '["PlayStation 4", "PlayStation 2"]', NULL, 8.5, 0, 7.05, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
