VALUES (NULL, NULL, 1530, 'Jak 3', 'Jak 3', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6kks.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/puon3jdmy7ws0ghkfckp.jpg', 'Jak 3 is a platform game developed by Naughty Dog for Sony''s PlayStation 2 console. The game is the sequel to Jak II, and third in the series. The game features new weapons and devices, new playable areas, and a storyline that picks up after the events of the previous games. As in the other games in the series, the player takes on the dual role of recurring protagonists Jak and Daxter.', 'https://www.igdb.com/games/jak-3', '["PlayStation 4", "PlayStation 2"]', NULL, 7.3, 0, 7.05, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
