VALUES (NULL, NULL, 105738, 'Project Warlock', 'Project Warlock', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1yif.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard7u.jpg', 'Project Warlock is a first person shooter that fans of Doom, Hexen and Wolfenstein cannot miss. It serves you an exploding cocktail of bullets, spells and monsters. Battle through 60 levels of non stop action packed with bloodthirsty enemies and challenging bosses.', 'https://www.igdb.com/games/project-warlock', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, 6.1, 0, 9.03, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
