VALUES (NULL, NULL, 7643, 'Shadowrun', 'Shadowrun', 'game', 2007, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5z85.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2edb.jpg', 'Shadowrun is a first-person shooter introducing mild cyberpunk elements to the gameplay. The game takes place in Brazil in the year 2031: before the events that shaped the Shadowrun universe. The player chooses between two factions to play as: The megacorp RNA Global, and the resistance group known as The Lineage. Playable races are Human, Elf, Troll, and Dwarf. Each race has their own unique racial traits.', 'https://www.igdb.com/games/shadowrun--2', '["PC (Microsoft Windows)", "Xbox 360"]', NULL, 6.2, 0, 9.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
