VALUES (NULL, NULL, 153415, 'Mud and Blood', 'Mud and Blood', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3h9n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar20ii.jpg', 'Mud and Blood, the cult classic flash strategy game is back with a vengeance and this time you are on the offensive. This is a brutal real-time strategy game set in World War 2 where you command a small squad of soldiers against impossible odds in a procedural and unforgiving battlefield.', 'https://www.igdb.com/games/mud-and-blood', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 7.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
