VALUES (NULL, NULL, 56020, 'Mud and Blood 2', 'Mud and Blood 2', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wtazcltfpckanlg88m7y.jpg', NULL, 'Mud and Blood 2 is a real-time tactical level strategy game. The player takes command of a squad of American soldiers during World War II (operation Lüttich, August 1944), who will face endless waves of German troops.', 'https://www.igdb.com/games/mud-and-blood-2', '["Web browser", "PC (Microsoft Windows)"]', NULL, NULL, 0, 0.0, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
