VALUES (NULL, NULL, 303808, 'Dynasty Warriors: Origins', 'Dynasty Warriors: Origins', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob1tq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar33mf.jpg', 'Experience an unrivaled sense of realism on the battlefield, fueled by exhilarating 1 vs. 1,000 action and the rush of massive armies! A nameless hero conquers the turbulent and chaotic Three Kingdoms in this latest DYNASTY WARRIORS series entry.', 'https://www.igdb.com/games/dynasty-warriors-origins', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.7, 0, 9.55, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
