VALUES (NULL, NULL, 164250, 'Ultimate Epic Battle Simulator 2', 'Ultimate Epic Battle Simulator 2', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3pbh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arzw1.jpg', 'Welcome to Ultimate Epic Battle Simulator 2, the most ridiculous and insane battle simulator in existence! Create eye watering battles with hundreds of thousands, even millions of characters on screen! Jump into multiple campaigns in game or player made, or play in sandbox mode and FPS invasion', 'https://www.igdb.com/games/ultimate-epic-battle-simulator-2--1', '["PC (Microsoft Windows)"]', NULL, 5.3, 0, 9.52, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
