VALUES (NULL, NULL, 7094, 'N3: Ninety-Nine Nights', 'N3: Ninety-Nine Nights', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2qsp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc7ien.jpg', 'Ninety-Nine Nights, is a fantasy hack and slash video game developed for the Xbox 360 by an alliance between Q Entertainment and Phantagram; video game designer Tetsuya Mizuguchi served as producer for the game.', 'https://www.igdb.com/games/n3-ninety-nine-nights', '["Xbox 360"]', NULL, 7.0, 0, 7.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
