VALUES (NULL, NULL, 12517, 'Undertale', 'Undertale', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob1t2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar61ar.jpg', 'A small child falls into the Underground, where monsters have long been banished by humans and are hunting every human that they find. The player controls the child as they try to make it back to the Surface through hostile environments, all the while engaging with a turn-based combat system with puzzle-solving and bullet hell elements, as well as other unconventional game mechanics.', 'https://www.igdb.com/games/undertale', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, 9.1, 0, 9.02, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
