VALUES (NULL, NULL, 171233, 'Deltarune', 'Deltarune', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9m71.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3tpf.jpg', 'Dive into the parallel story to UNDERTALE! Fight or spare your way through action-packed battles as you explore a mysterious world alongside an endearing cast of new and familiar characters.', 'https://www.igdb.com/games/deltarune', '["PlayStation 4", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Nintendo Switch"]', NULL, 8.4, 0, 9.02, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
