VALUES (NULL, NULL, 8492, 'Lisa: The Painful', 'Lisa: The Painful', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1odr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arqo6.jpg', 'Lisa is a quirky side-scrolling RPG set in a post-apocalyptic wasteland. Beneath the charming and funny exterior is a world full of disgust and moral destruction. Players will learn what kind of person they are by being FORCED to make choices. These choices permanently effect the game play. If you want to save a party member from death, you will have to sacrifice the strength of your character. Whether it''s taking a beating for them, or chopping off limbs, or some other inhuman way. You will learn that in this world being selfish and heartless is the only way to survive...', 'https://www.igdb.com/games/lisa-the-painful', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 9.0, 0, 10.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
