VALUES (NULL, NULL, 3683, 'Mother 3', 'Mother 3', 'game', 2006, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa3qi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1vmm.jpg', 'A turn-based JRPG and sequel to EarthBound (1994) in which a tragedy surrounding a family in the primitive yet joyful village of Tazmily incites the coming-of-age story of Lucas, the family''s younger son, who goes on perilous adventures along with his friends in order to find his missing brother and stop a group of masked men from bringing about the end of the world.', 'https://www.igdb.com/games/mother-3', '["Wii U", "Game Boy Advance"]', NULL, 9.0, 0, 10.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
