VALUES (NULL, NULL, 26673, 'Omori', 'Omori', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1xlp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arive.jpg', 'A turn-based surreal horror RPG in which a child traverses various mundane, quirky, humourous, mysterious and horrific lands with his friends in search of a missing person while confronting his past and his fears. Explore a strange world full of colorful friends and foes. When the time comes, the path you’ve chosen will determine your fate... and perhaps the fate of others as well.', 'https://www.igdb.com/games/omori', '["Xbox Series X|S", "PlayStation 4", "Nintendo 3DS", "PC (Microsoft Windows)", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, 8.6, 0, 0.0, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
