VALUES (NULL, NULL, 4104, 'Monster Rancher', 'Monster Rancher', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5xuq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scke8h.jpg', 'Monster Rancher is a console game released in 1997 for the PlayStation system. It is the first game in Tecmo''s Monster Rancher series, featuring the raising, fighting, and breeding of monsters.', 'https://www.igdb.com/games/monster-rancher', '["PlayStation"]', NULL, 5.2, 0, 9.55, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
