VALUES (NULL, NULL, 38877, 'Dragon City', 'Dragon City', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2sj0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6ge0.jpg', 'Build yourself a magical city and fill it with buildings, habitats, and dragons! Feed your dragons and make them evolve into strong beasts! You''ll be able to train them and teach them new skills. Collect over 600 dragons of different elements and rarities to complete the Dragon Book. You can become the top collector in the game! Battle against other players in the Dragon Leagues and face exciting challenges in the tournaments to win lots of rewards!', 'https://www.igdb.com/games/dragon-city', '["Web browser", "Android", "PC (Microsoft Windows)", "iOS"]', NULL, 3.1, 0, 0.0, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
