VALUES (NULL, NULL, 338104, 'The Duskbloods', 'The Duskbloods', 'game', 2027, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocqn8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5gan.jpg', 'An online multiplayer PvPvE game where players vie for supremacy among themselves and against challenging foes. Play as the "Bloodsworn"; a group that has transcended human strength thanks to their special blood, and throw yourself into a violent fray for "First Blood" as the twilight of humanity approaches. The moontears will flow for one and one alone.', 'https://www.igdb.com/games/the-duskbloods', '["Nintendo Switch 2"]', NULL, NULL, 0, 9.04, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
