VALUES (NULL, NULL, 250630, 'Marathon', 'Marathon', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc5yb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3f2q.jpg', 'A PvP-focused extraction shooter set on the mysterious planet of Tau Ceti IV, Marathon will see players inhabit the bodies of Runners, cybernetic mercenaries who have been designed to survive the planet’s harsh environments and explore the lost colony that once inhabited Tau Ceti’s surface. Players will engage solo or in crews of three, searching for mysterious alien artifacts, as well as for valuable loot and new weapons and gear that they can add to their collection.', 'https://www.igdb.com/games/marathon--2', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.9, 0, 9.03, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
