VALUES (NULL, NULL, 24412, 'Ark: Survival of the Fittest', 'Ark: Survival of the Fittest', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9k2x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/de0aj4bwrmiagag6bsdq.jpg', 'ARK: Survival of the Fittest is a Multiplayer Online Survival Arena (MOSA) game that pits as many as 72 combatants against one another in the struggle for survival in a harsh, changing environment packed with deadly creatures, “Evolution Events,” and other players.', 'https://www.igdb.com/games/ark-survival-of-the-fittest', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 1.5, 0, 9.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
