VALUES (NULL, NULL, 3055, 'Rampage', 'Rampage', 'game', 1986, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5ys2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/irfpv0lbdohkoj5fnoef.jpg', 'Rampage is a game where players control giant monsters/mutated humans. Players must smash buildings while destroying vehicles such as tanks, planes, and trains to advance to the next level. Smashing windows will sometimes reveals items of interest that the player may use.', 'https://www.igdb.com/games/rampage', '["Arcade"]', NULL, 7.5, 0, 8.52, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
