VALUES (NULL, NULL, 3935, 'Godzilla: Destroy All Monsters Melee', 'Godzilla: Destroy All Monsters Melee', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dz1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/draidzghxtpbyvfntj9x.jpg', 'Godzilla: Destroy All Monsters Melee is a fighting game developed and published by Pipeworks Software, Inc. for the Nintendo GameCube in 2002. The game was later released for Game Boy Advance as Godzilla: Domination!. A version for the Xbox with additional content was released in 2003. A PlayStation 2 version was planned, but later cancelled.', 'https://www.igdb.com/games/godzilla-destroy-all-monsters-melee', '["Xbox", "Nintendo GameCube", "PlayStation 2"]', NULL, 6.9, 0, 9.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
