VALUES (NULL, NULL, 78940, 'Ultraman Fighting Evolution', 'Ultraman Fighting Evolution', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8yql.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8cos.jpg', 'Ultraman Fighting Evolution (ウルトラマン ファイティングエボリューション Urutoraman Faitingu Eboryūjyon) is a fighting game. It was developed and published by Banpresto. It was the first Ultraman Fighting Evolution series game, spawning many sequels.', 'https://www.igdb.com/games/ultraman-fighting-evolution', '["PlayStation"]', NULL, NULL, 0, 8.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
