VALUES (NULL, NULL, 206833, 'Ultra Kaiju Monster Rancher', 'Ultra Kaiju Monster Rancher', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4x79.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1xb8.jpg', 'Ultra Kaiju: Monster Farm is the ultra monster breeding simulator, where players act as a kaiju breeder to raise partner monsters and win competitions to become the strongest breeder. Raise your partner monsters in a variety of ways, such as feeding, training, and adventuring. Training will improve your partner monster''s abilities, and training will help you learn new skills.', 'https://www.igdb.com/games/ultra-kaiju-monster-rancher', '["Nintendo Switch"]', NULL, NULL, 0, 10.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
