VALUES (NULL, NULL, 4271, 'Primal Rage', 'Primal Rage', 'game', 1994, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co309j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5llo.jpg', 'Primal Rage is a one-on-one fighting game featuring dinosaurs and giant apes as the fighters. The graphics are done with digitized stop-motion animation. Gameplay is similar to Mortal Kombat in that it is viewed from a side perspective, and features deadly finishing moves at the end of the match.', 'https://www.igdb.com/games/primal-rage', '["Arcade", "Super Nintendo Entertainment System", "Sega 32X", "Sega Mega Drive/Genesis", "3DO Interactive Multiplayer", "DOS", "Amiga", "Atari Jaguar CD", "Sega Saturn", "PlayStation"]', NULL, 5.4, 0, 10.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
