VALUES (NULL, NULL, 112483, 'The Enigma Machine', 'The Enigma Machine', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2cum.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1c49.jpg', 'ENIGMA TECHNOLOGIES invites you to delve into the mind of an AI. Seamlessly blending first-person exploration with point-and-click mechanics, THE ENIGMA MACHINE''s completely unique presentation offers an increasingly unnerving atmosphere.', 'https://www.igdb.com/games/the-enigma-machine', '["PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 9.52, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
