VALUES (NULL, NULL, 147807, 'Baroque', 'Baroque', 'game', 1998, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co30f3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3u8i.jpg', 'Baroque is horror-themed action game with elements of survival gameplay. The whole game is set in the tower: you slowly work your way to the top, fighting demons as you progress. You have HP as well as stamina gauge. If your stamina is depleted, you walk slower and can''t react well in a battle.', 'https://www.igdb.com/games/baroque--1', '["PlayStation 3", "Sega Saturn", "PlayStation", "PlayStation Portable", "Nintendo Switch"]', NULL, NULL, 0, 9.51, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
