VALUES (NULL, NULL, 26565, 'Yuppie Psycho', 'Yuppie Psycho', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1n1e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar49i.jpg', 'Join Brian Pasternack on his first day at one of the world’s largest companies, Sintracorp. Uncertain, unprepared, and massively unqualified, will Pasternack have what it takes to shine in Sintracorp''s hierarchy? It all depends on how he performs on his first assignment… and whether he survives it.', 'https://www.igdb.com/games/yuppie-psycho', '["Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.8, 0, 10.03, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
