VALUES (NULL, NULL, 304201, 'Ad Nauseam', 'Ad Nauseam', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cod8eb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6w5i.jpg', 'Ad Nauseam is a choice-heavy psych horror / thriller about trauma, identity, love, and sickness. It combines many staples of Adventure, VN, and RPG games with its own flair to create something entirely unique. Solve mysteries, form bonds, blur the line between mind and body, and keep your eyes open.', 'https://www.igdb.com/games/ad-nauseam', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 10.0, 0, 9.02, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
