VALUES (NULL, NULL, 133256, 'You and Me and Her: A Love Story', 'You and Me and Her: A Love Story', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co45x8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar112s.jpg', 'You and Me and Her: A Love Story is the visual novel medium in its purest form. Will Shinichi choose Miyuki, the beautiful queen bee of the school, or the endearingly awkward misfit Aoi? With art by Tsuji Santa, these beautifully rendered romances will stay with you forever.', 'https://www.igdb.com/games/you-and-me-and-her-a-love-story', '["PC (Microsoft Windows)"]', NULL, 7.5, 0, 9.04, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
