VALUES (NULL, NULL, 329148, 'Drone Sector', 'Drone Sector', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocapv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6522.jpg', 'Drone Sector is a futuristic gunship game. Provide close air support by firing variety of weapons at the enemies and guide your allied troops via commands. Keep your troops alive, complete objectives, collect resources and recruit engineers. Research better weaponry for the gunship and the troops.', 'https://www.igdb.com/games/drone-sector', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 1.26, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
