VALUES (NULL, NULL, 531, 'Ace Combat: Assault Horizon', 'Ace Combat: Assault Horizon', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2egz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/wo4qxp3qtbcetys7gi8h.jpg', 'Ace Combat: Assault Horizon is the 14th game released in the Ace Combat series. It took place in the real world, albeit in a different timeline from that of Joint Assault. Players took control of various members of Task Force 108, most notably William Bishop, as they shut down the threat posed by Andrei Markov and other rebels from Russia.', 'https://www.igdb.com/games/ace-combat-assault-horizon', '["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 7.6, 0, 1.06, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
