VALUES (NULL, NULL, 47128, 'VTOL VR', 'VTOL VR', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8x8n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armvi.jpg', 'VTOL VR is a near-futuristic combat flight game built specifically for Virtual Reality. Pilot advanced multi-role jets, using your hands to flip switches, press buttons, and manipulate the virtual flight controls. Take on a wide array of challenges that will put your flight skills, situational awareness, and combat tactics to the test.', 'https://www.igdb.com/games/vtol-vr', '["SteamVR"]', NULL, 8.4, 0, 1.04, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
