VALUES (NULL, NULL, 129097, 'Norco', 'Norco', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3nu3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8zq.jpg', 'Norco is a Southern Gothic point & click narrative adventure that immerses the player in the sinking suburbs and verdant industrial swamps of a distorted South Louisiana. Your brother Blake has gone missing in the aftermath of your mother''s death. In the hopes of finding him, you must follow a fugitive security android through the refineries, strip malls, and drainage ditches of suburban New Orleans.', 'https://www.igdb.com/games/norco', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, 8.5, 0, 1.04, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
