VALUES (NULL, NULL, 230366, 'Into the Dead: Our Darkest Days', 'Into the Dead: Our Darkest Days', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7wq3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar25z6.jpg', 'Texas, 1980. Walton City has fallen to a zombie outbreak. Lead a band of desperate survivors from refuge to refuge by scavenging, crafting, and fighting in a relentless struggle for survival. Plan wisely, stick together, and — above all — keep moving if you want to make it out alive.', 'https://www.igdb.com/games/into-the-dead-our-darkest-days', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, NULL, 0, 1.24, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
