VALUES (NULL, NULL, 8209, 'Mordheim: City of the Damned', 'Mordheim: City of the Damned', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1odq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arlj4.jpg', 'Mordheim: City of the Damned is the first video game adaptation of Games Workshop''s cult classic tabletop game Mordheim. Set in the Warhammer World''s decimated Empire city, Mordheim: City of the Damned is a turn-based tactical game where you lead warbands into bloody and lethal skirmishes. The game blends RPG elements, fast-paced tactical combat and intricate unit customization in a time wrought by chaos and rivalry where only the strongest survive.', 'https://www.igdb.com/games/mordheim-city-of-the-damned', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', NULL, 7.7, 0, 1.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
