VALUES (NULL, NULL, 9571, 'Star Trek: Bridge Commander', 'Star Trek: Bridge Commander', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e97.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar12qt.jpg', 'Star Trek: Bridge Commander is a space simulation set in the Star Trek universe just after the Dominion War, but before Star Trek Nemesis. It puts you in command of your own Starfleet vessel with the ability to coordinate with your senior staff. This game was published in 2002 for Windows PCs.', 'https://www.igdb.com/games/star-trek-bridge-commander', '["PC (Microsoft Windows)"]', NULL, 8.2, 0, 1.34, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
