VALUES (NULL, NULL, 40820, 'I-War', 'I-War', 'game', 1995, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co986p.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scjn4c.jpg', 'I-War is a 3D virtual reality tank game. In each of the 21 levels, you must find all the data pods and make your way to the exit. Enemy tanks, turrets, and bombers stand in your way, as well as occasional traps or locked doors controlled by hidden switches. Levels are divided into simple, enclosed rooms, linearly connected by one-way teleporters.', 'https://www.igdb.com/games/i-war', '["Atari Jaguar"]', NULL, NULL, 0, 1.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
