VALUES (NULL, NULL, 107875, 'Radio Commander', 'Radio Commander', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2i4u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ard66.jpg', 'Use the radio to give commands to the soldiers on the battlefield. Keep track of the situation based on their voice reports only. Lead US platoons to clash with Vietcong in a realistic, innovative approach to the RTS genre. Make hard choices in a narrative driven experience, and face the outcome.', 'https://www.igdb.com/games/radio-commander', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.0, 0, 1.26, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
