VALUES (NULL, NULL, 1800, 'Sly 3: Honor Among Thieves', 'Sly 3: Honor Among Thieves', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1p0q.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3ssk.jpg', 'Sly 3: Honor Among Thieves is a stealth-action platformer developed by Sucker Punch Productions and released for PlayStation 2 in 2005. The game follows Sly Cooper and his crew as they recruit new allies to help unlock the Cooper Vault while facing off against Dr. M, a former member of Sly’s family lineage. It introduces new playable characters, expanded mini-games, and a 3D mode with optional glasses.', 'https://www.igdb.com/games/sly-3-honor-among-thieves', '["PlayStation 2"]', NULL, 7.9, 0, 1.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
