VALUES (NULL, NULL, 158064, 'Bears In Space', 'Bears In Space', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7q1i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar212s.jpg', 'Unleash your inner bear in this over-the-top bullet-hell FPS! Embark on a zany retro-futuristic adventure and destroy oil-thirsty robots with an outrageous arsenal. Transform into a bear, wield unique powers, and embrace the absurd fast-paced action of Bears in Space!', 'https://www.igdb.com/games/bears-in-space', '["PC (Microsoft Windows)"]', NULL, 8.0, 0, 1.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
