VALUES (NULL, NULL, 11710, '60 Parsecs!', '60 Parsecs!', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1i66.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcqr.jpg', '60 Parsecs! is an Atomic Space Age adventure of scavenge and survival. Keep your crew alive and ready for action. Make difficult choices, face soup shortages and other horrors of outer space. And maybe reach your destination. Or not.', 'https://www.igdb.com/games/60-parsecs', '["PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 6.0, 0, 1.02, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
