VALUES (NULL, NULL, 15857, 'Headlander', 'Headlander', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/uyhtdsepz3tsqi9j55m5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3nvd.jpg', 'Launch into the ultimate head trip as you blast through psychotic robots in a retro 70''s sci-fi action adventure from Double Fine Productions. It is a world of automation, a utopia gone wrong in which all of humanity have transferred their minds into robotic imposter bodies and are ruled by a computer.', 'https://www.igdb.com/games/headlander', '["PlayStation 4", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.7, 0, 1.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
