VALUES (NULL, NULL, 70, 'Terra Nova: Strike Force Centauri', 'Terra Nova: Strike Force Centauri', 'game', 1996, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2y5l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5hwv.jpg', 'Lead an elite fighting team battling for freedom from the sinister forces of the Earth Hegemony. Engage in combat on the bloody battlefields of four unique worlds. Encased in your Powered Battle Armour (PBA) you are an unstoppable fighting force.', 'https://www.igdb.com/games/terra-nova-strike-force-centauri', '["Linux", "PC (Microsoft Windows)", "Mac", "DOS"]', NULL, 8.6, 0, 1.01, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
