VALUES (NULL, NULL, 381250, 'Highguard', 'Highguard', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob0ha.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4v26.jpg', 'From the creators of Apex Legends and Titanfall, comes Highguard: a PvP raid shooter where players will ride, fight, and raid as Wardens, arcane gunslingers sent to fight for control of a mythical continent.', 'https://www.igdb.com/games/highguard', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 6.3, 0, 1.03, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
