VALUES (NULL, NULL, 8410, 'Happy Wars', 'Happy Wars', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2smp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1bs2.jpg', 'Happy Wars is an action-packed massive online multiplayer game where you can play together with as many as 30 players in one online session. And, it’s free-to-play. Team up with players all over the world and go crazy in wacky melees in a fantastic realm of heated sieges and big magical battles. Get premium items of beautiful graphic quality through Happy Cards and other means to power up your character. Charge through battlefields with your own personalized character.', 'https://www.igdb.com/games/happy-wars', '["PC (Microsoft Windows)", "Xbox 360", "Xbox One"]', NULL, 6.5, 0, 0.0, '2026-11-27 20:45:57', '2026-11-27 20:45:57')
