VALUES (NULL, NULL, 14362, 'Detroit: Become Human', 'Detroit: Become Human', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocot9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4na7.jpg', 'Detroit: Become Human is an interactive narrative adventure game developed by Quantic Dream and released in 2018. Set in a near-future Detroit where androids serve humans, the story follows three android protagonists—Kara, Connor, and Markus—who shape the city’s fate through their choices. Gameplay combines exploration, dialogue interactions, and quick-time events, with branching storylines and multiple endings. The narrative explores themes of artificial intelligence, freedom, and morality.', 'https://www.igdb.com/games/detroit-become-human--1', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, 8.0, 0, 4.836666666666666e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
