VALUES (NULL, NULL, 23, 'System Shock', 'System Shock', 'game', 1994, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4e44.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/czvaliya2h72p6jhkffm.jpg', 'A seminal cyberpunk first-person exploratory adventure game with RPG elements in which, waking up in the Citadel Space Station, a lone hacker has to survive corrupted enemies and collect audio logs and equipment from former station workers in order to shut down SHODAN, the station''s artificial intelligence that has killed everyone on board and now intends to destroy the world.', 'https://www.igdb.com/games/system-shock', '["PC-9800 Series", "PC (Microsoft Windows)", "Mac", "DOS"]', NULL, 9.1, 0, 4.51500000000000056e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
