VALUES (NULL, NULL, 32283, 'UBoat', 'UBoat', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co269d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arj2z.jpg', 'UBOAT is a simulator of a submarine from WWII era. It is a survival sandbox with crew management mechanics while its primary theme is life of German sailors. The boat is their home, but it can become their grave at any time.', 'https://www.igdb.com/games/uboat', '["PC (Microsoft Windows)", "PlayStation 5", "Mac"]', NULL, 7.0, 0, 5.70333333333333314e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
