VALUES (NULL, NULL, 228542, 'Armored Core VI: Fires of Rubicon', 'Armored Core VI: Fires of Rubicon', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc408.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ek8.jpg', 'By combining FromSoftware’s longstanding expertise in mech games and their signature robust gameplay, Armored Core VI: Fires of Rubicon will be a new action experience.', 'https://www.igdb.com/games/armored-core-vi-fires-of-rubicon', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 8.3, 0, 11.895, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
