VALUES (NULL, NULL, 102058, 'Outriders', 'Outriders', 'game', 2021, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2e4r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5s2.jpg', 'Outriders is a 1-3 player co-op RPG shooter set in an original, dark and desperate sci-fi universe. As mankind bleeds out in the trenches of Enoch, you’ll create your own Outrider and embark on a journey across the hostile planet. With rich storytelling spanning a diverse world, you’ll leave behind the slums and shanty towns of the First City and traverse forests, mountains and desert in the pursuit of a mysterious signal. Combining intense gunplay with violent powers and an arsenal of increasingly twisted weaponry and gear-sets, Outriders offers countless hours of gameplay.', 'https://www.igdb.com/games/outriders', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.6, 0, 1.06833333333333335e+01, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
