VALUES (NULL, NULL, 23181, 'OneShot', 'OneShot', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u08.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arkw7.jpg', 'OneShot is a surreal top down puzzle/adventure game with unique gameplay capabilities. You are to guide a child through a mysterious world on a mission to restore its long-dead sun. The world knows you exist.', 'https://www.igdb.com/games/oneshot', '["Linux", "PC (Microsoft Windows)", "Mac"]', NULL, 8.3, 0, 1.05166666666666657e+01, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
