VALUES (NULL, NULL, 28574, 'Surviving Mars', 'Surviving Mars', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1kvs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/blekpht2rqgbmvapyfyc.jpg', 'Surviving Mars is a sci-fi city builder all about colonizing Mars and surviving the process. Choose a space agency for resources and financial support before determining a location for your colony. Build domes and infrastructure, research new possibilities and utilize drones to unlock more elaborate ways to shape and expand your settlement. Cultivate your own food, mine minerals or just relax by the bar after a hard day’s work. Most important of all, though, is keeping your colonists alive. Not an easy task on a strange new planet.', 'https://www.igdb.com/games/surviving-mars', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 7.2, 0, 8.34666666666666579e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
