VALUES (NULL, NULL, 377917, 'Iron Nest: Heavy Turret Simulator', 'Iron Nest: Heavy Turret Simulator', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaupt.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6aqe.jpg', 'Iron Nest is a brutal dieselpunk heavy-artillery game where you dominate the battlefield through a colossal war machine. Take map measurements based on the received coordinates, strain the hydraulics, and gunlay the cannons to unleash devastating blows ⟹ Will you obey High Command, Operator?', 'https://www.igdb.com/games/iron-nest-heavy-turret-simulator', '["PC (Microsoft Windows)"]', NULL, NULL, 0, 8.754999999999999e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
