VALUES (NULL, NULL, 322158, 'Active Matter', 'Active Matter', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocv7g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar395g.jpg', 'You’re an operative stuck in a time loop, always brought back from the dead to the same point.

Choose your loadout and enter quantum unstable zones rich with active matter — a substance capable of warping and ripping the very fabric of space and time.

Fight against rivals from other timelines, survive physics-breaking anomalies and try to stay alive. Harvest active matter, gather loot and extract to a safe place before the whole zone ceases to exist with everything inside it.', 'https://www.igdb.com/games/active-matter', '["Xbox Series X|S", "Linux", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 9.0, 0, 5.535, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
