VALUES (NULL, NULL, 8074, 'Pathologic', 'Pathologic', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3qvl.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhw8.jpg', 'Pathologic is a Russian survival-horror/RPG about a remote steppe town collapsing under a plague, with the story told through three playable outsiders: the Bachelor, the Haruspex, and the Changeling. Each route covers the same 12-day catastrophe from a different worldview, but rather than offering a clean mystery to unravel, the game forces you to survive inside a collapsing social order where resources are scarce, motives are unclear, and every explanation of the town feels partial or suspect.', 'https://www.igdb.com/games/pathologic', '["PC (Microsoft Windows)"]', NULL, 7.3, 0, 1.25300000000000011e+01, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
