VALUES (NULL, NULL, 11171, 'Tom Clancy''s Ghost Recon: Wildlands', 'Tom Clancy''s Ghost Recon: Wildlands', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ku7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4uo.jpg', 'Create a team with up to 3 friends in Tom Clancy''s Ghost Recon Wildlands and enjoy the ultimate military shooter experience set in a massive, dangerous, and responsive open world.', 'https://www.igdb.com/games/tom-clancys-ghost-recon-wildlands', '["Google Stadia", "Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.3, 0, 1.65661538461538455e+01, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
