VALUES (NULL, NULL, 388285, 'Wardogs', 'Wardogs', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocs6d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6f0b.jpg', 'Wardogs is a first-person tactical multiplayer shooter built around large-scale combined-arms battles for up to 100 players. Three teams compete to control randomized objective zones across destructible battlefields, using infantry weapons, vehicles, logistics, fortifications, and proximity voice chat.

Players earn cash and XP through combat, support, transportation, and objective play, then spend persistent cash on custom loadouts, equipment, and vehicles across lives and matches.', 'https://www.igdb.com/games/wardogs', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 8.0, 0, 6.84333333333333282e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
