VALUES (NULL, NULL, 996, 'Army of Two', 'Army of Two', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5x88.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8ki.jpg', 'Army Of Two throws gamers into hot spots ripped from current day headlines where they will utilize unique two-man strategies and tactics while seamlessly transitioning between playing with intelligent Partner AI (PAI) and a live player. When one man is not enough, it will take an army of two to fight through war, political turmoil and a conspiracy so vast it threatens the entire world', 'https://www.igdb.com/games/army-of-two', '["PlayStation 3", "Xbox 360"]', NULL, 6.9, 0, 8.53000000000000113e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
