VALUES (NULL, NULL, 204538, 'Once Human', 'Once Human', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocqpb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6cdn.jpg', 'Once Human is a multiplayer open-world survival game set in a strange, post-apocalyptic future. Unite with friends to fight monstrous enemies, uncover secret plots, compete for resources, and build your own territory. Once, you were merely human. Now, you have the power to remake the world.', 'https://www.igdb.com/games/once-human', '["Xbox Series X|S", "Android", "PC (Microsoft Windows)", "iOS", "PlayStation 5"]', NULL, 7.5, 0, 8.35, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
