VALUES (NULL, NULL, 291212, 'Void War', 'Void War', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8yj0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2t8x.jpg', 'Command an ancient starship and fight your way to the heart of a dying Empire. Fend off attacks from demented cultists, craven space pirates, and xenophobic Imperial soldiers. Discover powerful artifacts and use them to build your ship into a fearsome war engine.', 'https://www.igdb.com/games/void-war--1', '["PC (Microsoft Windows)"]', NULL, 7.7, 0, 6.22000000000000064e+00, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
