VALUES (NULL, NULL, 198137, 'Serious Sam', 'Serious Sam', 'game', 2002, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ocg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scgozh.jpg', 'A port of Serious Sam: The First Encounter and Serious Sam: The Second Encounter for Xbox that compiles them into one cohesive game. Features a visual makeover with a redesigned menu and main character model which are far more cartoonish, alongside expanded story cutscenes.', 'https://www.igdb.com/games/serious-sam', '["Xbox"]', NULL, 8.3, 0, 7.06, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
