VALUES (NULL, NULL, 13, 'Fallout: A Post Nuclear Role Playing Game', 'Fallout: A Post Nuclear Role Playing Game', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ybn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1qjx.jpg', 'The Vault Dweller is tasked with exploring post-nuclear California in order to retrieve a water chip to replace the broken chip of Vault 13, their home, which they are the first person to ever leave. The player will engage in Western RPG character building and turn-based tactical combat while getting to know settlements and factions of people, mutants and ghouls through branching dialogue trees.', 'https://www.igdb.com/games/fallout-a-post-nuclear-role-playing-game', '["OnLive Game System", "Linux", "PC (Microsoft Windows)", "Mac", "DOS"]', NULL, 8.6, 0, 7.745, '2026-11-19 20:56:22', '2026-11-27 20:45:57')
