VALUES (NULL, NULL, 158985, 'Final Fantasy VI', 'Final Fantasy VI', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ple.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar52ko.jpg', 'The original Final Fantasy VI comes to life with completely new graphics and audio! A remodeled 2D take on the sixth game in the world-renowned Final Fantasy series! Enjoy the timeless story told through charming retro graphics.', 'https://www.igdb.com/games/final-fantasy-vi--2', '["Xbox Series X|S", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Nintendo Switch"]', NULL, 8.2, 0, 13.145, '2026-11-20 01:06:03', '2026-11-27 20:45:57')
