VALUES (NULL, NULL, 10919, 'XCOM 2', 'XCOM 2', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mvj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4w8.jpg', 'XCOM 2 is the sequel to XCOM: Enemy Unknown, the 2012 award-winning strategy game of the year. Earth has changed and is now under alien rule. Facing impossible odds you must rebuild XCOM, and ignite a global resistance to reclaim our world and save humanity.', 'https://www.igdb.com/games/xcom-2', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One", "Nintendo Switch"]', NULL, 8.4, 0, 13.18, '2026-11-20 01:06:03', '2026-11-27 20:45:57')
