VALUES (NULL, NULL, 56859, 'Project Wingman', 'Project Wingman', 'game', 2020, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2g1b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arjgr.jpg', 'Project Wingman is an independently developed combat flight action game with an emphasis on fun and refined gameplay, true-to-its-roots inspirations, and an engaging single player experience. Perfect for those who aren''t looking for a simulator experience with the ease of pick up and play, all the way to those who want a fast-paced challenging flight action game.', 'https://www.igdb.com/games/project-wingman', '["PC (Microsoft Windows)", "SteamVR", "Xbox One"]', NULL, 8.1, 0, 9.33333333333333392e+00, '2026-11-21 13:07:40', '2026-11-27 20:45:57')
