VALUES (NULL, NULL, 138906, 'The Invincible', 'The Invincible', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co61ol.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/armny.jpg', 'Rethink human’s dominion in The Invincible: a story-driven adventure set in a hard sci-fi world by Stanisław Lem. Discover planet Regis III as scientist Yasna, use atompunk tools looking for a missing crew and face unforeseen threats. Make choices in a philosophical story that’s driven by science.', 'https://www.igdb.com/games/the-invincible', '["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, 7.5, 0, 9.12000000000000099e+00, '2026-11-21 13:07:40', '2026-11-27 20:45:57')
