VALUES (NULL, NULL, 14740, 'The Deadly Tower of Monsters', 'The Deadly Tower of Monsters', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co43pg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1d65.jpg', 'The Deadly Tower of Monsters is an action-packed adventure, full of time-honored literary themes: the daughter versus the tyrant father, the planet full of innocent ape-creatures, the dashing space-age liberator, the robot companion, the tower full of treacherous mutations... A timeless classic for all ages!', 'https://www.igdb.com/games/the-deadly-tower-of-monsters', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, 7.5, 0, 6.27, '2026-11-21 13:07:40', '2026-11-27 20:45:57')
