VALUES (NULL, NULL, 8709, 'Marathon', 'Marathon', 'game', 1994, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5u0y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mcb3cfalxjplukx96kdz.jpg', 'You are far in the future on a colony ship deep in outer space. A security officer on the mission, you are the last hope for defending the ship as hostile and intelligent aliens prepare to destroy every living thing…', 'https://www.igdb.com/games/marathon', '["iOS", "Mac"]', NULL, 8.0, 0, 5.52, '2026-11-21 21:29:28', '2026-11-27 20:45:57')
