VALUES (NULL, NULL, 152257, 'Wartales', 'Wartales', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6dpz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arupy.jpg', 'Wartales is an open world RPG in which you lead a group of mercenaries in their search for wealth across a massive medieval universe. Explore the world, recruit companions, collect bounties and unravel the secrets of the tombs of the ancients!', 'https://www.igdb.com/games/wartales', '["Xbox Series X|S", "PC (Microsoft Windows)", "Nintendo Switch"]', NULL, 8.3, 0, 6.25, '2026-11-21 21:29:28', '2026-11-27 20:45:57')
