VALUES (NULL, NULL, 4115, 'Syphon Filter', 'Syphon Filter', 'game', 1999, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y7j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/rfnuz5zbjzccpurzmrwm.jpg', 'Syphon Filter is a third-person shooter stealth video game developed by Eidetic and published by 989 Studios exclusively for PlayStation. The plot centers on special agents Gabriel "Gabe" Logan and Lian Xing who are tasked by the United States government to apprehend a German international terrorist.', 'https://www.igdb.com/games/syphon-filter', '["PlayStation 3", "Android", "PlayStation", "PlayStation Portable"]', NULL, 8.5, 0, 6.27, '2026-11-21 21:29:28', '2026-11-27 20:45:57')
