VALUES (NULL, NULL, 7291, 'Hunt: Showdown 1896', 'Hunt: Showdown 1896', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cocuvs.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar6qg6.jpg', 'Hunt the corrupted in backwaters lost to history. Fight back against a timeless evil that pits you against twisted monsters and other desperate Hunters – solo or in a group – in a high-stakes, tactical, PvPvE, first person shooter. There are no heroes here. Risk everything as Hunt consumes you.', 'https://www.igdb.com/games/hunt-showdown-1896', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, 7.5, 0, 8.54666666666666685e+00, '2026-11-21 21:29:28', '2026-11-27 20:45:57')
