VALUES (NULL, NULL, 1020, 'Grand Theft Auto V', 'Grand Theft Auto V', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lbd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m56.jpg', 'Grand Theft Auto V is a vast open world game set in Los Santos, a sprawling sun-soaked metropolis struggling to stay afloat in an era of economic uncertainty and cheap reality TV. The game blends storytelling and gameplay in new ways as players repeatedly jump in and out of the lives of the game’s three lead characters, playing all sides of the game’s interwoven story.', 'https://www.igdb.com/games/grand-theft-auto-v', '["Xbox Series X|S", "PlayStation 3", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox 360", "Xbox One"]', NULL, 8.9, 0, 7.34333333333333282e+00, '2026-11-21 21:29:28', '2026-11-27 20:45:57')
