VALUES (NULL, NULL, 18854, 'Let It Die', 'Let It Die', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1qiy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnsm.jpg', 'LET IT DIE is a hyper-violent hack-and-slash action experience with roguelike elements. Fight your way to the top in this free-to-play collaborative creation brought to you by Grasshopper Manufacture and GungHo Online Entertainment America.', 'https://www.igdb.com/games/let-it-die', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, 7.5, 0, 6.52999999999999936e+00, '2026-11-21 21:29:28', '2026-11-27 20:45:57')
