VALUES (NULL, NULL, 2955, 'Elite: Dangerous', 'Elite: Dangerous', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8jkn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar75s.jpg', 'The next game in the Elite series - an amazing space epic with stunning visuals, incredible gameplay, breath-taking scope and award-winning sound. All content can be enjoyed in game any mode: solo, personal invite-only group or open/MMO. Carve your own path through the richest, largest gaming sandbox ever created, a 1:1 scale representation of the Milky Way galaxy, set against a backdrop of raw anarchy, galactic powerplays and political intrigue.', 'https://www.igdb.com/games/elite-dangerous', '["PlayStation 4", "PC (Microsoft Windows)", "SteamVR", "Mac", "Oculus Rift", "Xbox One"]', NULL, 8.1, 0, 8.626, '2026-11-26 02:21:07', '2026-11-27 20:45:57')
