VALUES (NULL, NULL, 2001, 'Far Cry 3: Blood Dragon', 'Far Cry 3: Blood Dragon', 'game', 2013, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vpp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar7yh.jpg', 'There’s only one force powerful enough to stop an army of rampaging killer cyborgs, mutated scientists, metal sharks and vicious Blood Dragons that shoot lasers from their eyes – that force is you. Your name is Sergeant Rex Power Colt, a Mark IV Cyber Commando. Lock and load as you and your seven favorite fully customizable killing implements tackle a bizarre open world island crawling with evil. Take down the enemy with ninja stars, guns or even just good old explosives. Your battle. Your way. Their tough luck.', 'https://www.igdb.com/games/far-cry-3-blood-dragon', '["Google Stadia", "PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', NULL, 8.1, 0, 10.025, '2026-11-26 02:21:07', '2026-11-27 20:45:57')
