VALUES (NULL, NULL, 11599, 'Hylics', 'Hylics', 'game', 2015, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaad2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar40uy.jpg', 'Hylics is a recreational program with light JRPG elements.', 'https://www.igdb.com/games/hylics', '["PC (Microsoft Windows)"]', NULL, 7.8, 0, 6.605, '2026-11-26 23:52:17', '2026-11-27 20:45:57')
