VALUES (NULL, NULL, 1265, 'PlanetSide 2', 'PlanetSide 2', 'game', 2012, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2iq1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ps.jpg', 'PlanetSide 2 is a Massively Multiplayer first person shooter that delivers truly epic, massive combat on a scale never before seen in stunning, breathtaking detail. Battles take place not between dozens of troops, but thousands; with air and ground vehicles slugging it out alongside squads of troops. Whether in open fields, tightly-packed urban centers or enormous structures, winning requires strategic teamwork and a quick trigger finger.', 'https://www.igdb.com/games/planetside-2', '["PlayStation 4", "PC (Microsoft Windows)"]', NULL, 7.7, 0, 10.545, '2026-11-26 23:52:17', '2026-11-27 20:45:57')
