VALUES (NULL, NULL, 9182, 'We Happy Few', 'We Happy Few', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1nax.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qnty96i68fvz9myskaqs.jpg', 'We Happy Few is the tale of a plucky bunch of moderately terrible people trying to escape from a lifetime of cheerful denial. Set in a drug-fuelled, retrofuturistic city in an alternative 1960s England, you''ll have to blend in with its other inhabitants, who don''t take kindly to people who don''t abide by their not-so-normal rules.', 'https://www.igdb.com/games/we-happy-few', '["PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox One"]', NULL, 6.3, 0, 10.575, '2026-11-26 23:52:17', '2026-11-27 20:45:57')
